import math
import numpy as np
from scipy.integrate import solve_ivp

def predict(obj, launch):
    C = {"sphere": 0.736, "cube": 2.098, "cylinder": 1.276}
    g = 9.81
    m = float(obj["mass"]); r = float(obj["radius"])
    k = C.get(obj["shape"], 0.736) * float(launch["air_density"]) * r * r / m
    h = float(launch["height"]); sp = float(launch["speed"])
    th = math.radians(float(launch["angle"]))
    def f(t, s):
        vx, vy = s[2], s[3]
        v = math.hypot(vx, vy)
        return [vx, vy, -k * v * vx, -g - k * v * vy]
    def ev(t, s):
        return s[1]
    ev.terminal = True
    ev.direction = -1
    sol = solve_ivp(f, [0, 200], [0, h, sp * math.cos(th), sp * math.sin(th)],
                    events=ev, rtol=1e-8, atol=1e-10)
    if len(sol.t_events[0]) == 0:
        s = sol.y[:, -1]; t = sol.t[-1]
    else:
        s = sol.y_events[0][0]; t = sol.t_events[0][0]
    return {"flight_time": float(t), "distance": float(s[0]),
            "impact_speed": float(math.hypot(s[2], s[3]))}

